package gsfarmv3

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/alloc"
	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/core"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Phase 1 machine: WUGNOT deposits, 15% idle buffer, rest in GnoSwap
// GNS/WUGNOT LP. Withdraw unwinds the LP, swaps leftover GNS, then
// marks the book to cash so redeem never exceeds WUGNOT on hand.

type state struct {
	admin          address
	treasury       address
	self           address
	paused         bool
	book           *core.Book
	fees           core.FeeConfig
	guard          core.ReinvestGuard
	bufferBPS      int64
	positionID     uint64
	protocolEarned int64
	lastHarvest    int64
	lastDeployed   int64
}

var g *state

func init() {
	deployer := unsafe.OriginCaller()
	g = &state{
		admin:     deployer,
		treasury:  deployer,
		self:      unsafe.CurrentRealm().Address(),
		book:      core.NewBook(),
		fees:      core.DefaultFees(),
		guard:     core.DefaultGuard(),
		bufferBPS: alloc.DefaultBufferBPS,
	}
	g.guard.MinProfit = 0
}

func Admin() address               { return g.admin }
func Treasury() address            { return g.treasury }
func VaultAddress() address        { return g.self }
func Paused() bool                 { return g.paused }
func TotalAssets() int64           { return g.book.TotalAssets() }
func TotalShares() int64           { return g.book.TotalShares() }
func SharesOf(a address) int64     { return g.book.SharesOf(a) }
func PreviewDeposit(a int64) int64 { return g.book.PreviewDeposit(a) }
func PreviewRedeem(s int64) int64  { return g.book.PreviewRedeem(s) }
func Want() string                 { return liveWugnotKey }
func IdleWugnot() int64            { return idleWugnot() }
func PendingGns() int64            { return pendingGns() }
func PositionID() uint64           { return g.positionID }
func ProtocolEarned() int64        { return g.protocolEarned }
func LastHarvest() int64           { return g.lastHarvest }
func BufferBPS() int64             { return g.bufferBPS }
func CashWugnot() int64            { return idleWugnot() }

func SharePriceE6() int64 {
	if g.book.TotalShares() == 0 {
		return 1_000_000
	}
	return g.book.PreviewRedeem(1_000_000)
}

func TargetIdleWugnot() int64 {
	return alloc.TargetIdle(g.book.TotalAssets(), g.bufferBPS)
}

func Deposit(cur realm, amount int64) int64 {
	mustLive()
	if amount <= 0 {
		panic("amount must be positive")
	}
	caller := cur.Previous().Address()
	pullWugnot(cur, caller, amount)
	shares := g.book.Deposit(caller, amount)
	chain.Emit("Deposit", "user", caller.String(), "assets", strconv.FormatInt(amount, 10), "shares", strconv.FormatInt(shares, 10))
	return shares
}

// Withdraw burns shares and pays WUGNOT. If the idle buffer is too small it
// unwinds the LP and swaps leftover GNS first, then marks the book to cash
// so a large redeem cannot panic with "unwind did not cover withdraw".
func Withdraw(cur realm, shares int64) int64 {
	caller := cur.Previous().Address()
	need := g.book.PreviewRedeem(shares)
	if idleWugnot() < need {
		unwindAll(cur)
		syncBookToCash()
	}
	assets := g.book.Withdraw(caller, shares)
	have := idleWugnot()
	if assets > have {
		assets = have
	}
	pushWugnot(cur, caller, assets)
	chain.Emit("Withdraw", "user", caller.String(), "shares", strconv.FormatInt(shares, 10), "assets", strconv.FormatInt(assets, 10))
	return assets
}

func Reinvest(cur realm) int64 {
	mustLive()
	now := time.Now().Unix()
	height := runtime.ChainHeight()
	if g.guard.LastHeight != 0 && height <= g.guard.LastHeight {
		panic("reinvest too soon")
	}

	profit := harvestLP(cur)
	rest := int64(0)
	if profit > 0 {
		callerAmt, protoAmt, compound := core.SplitHarvest(profit, g.fees)
		if compound > 0 {
			g.book.AddProfit(compound)
		}
		if callerAmt > 0 {
			pushWugnot(cur, cur.Previous().Address(), callerAmt)
		}
		if protoAmt > 0 {
			pushWugnot(cur, g.treasury, protoAmt)
			next, ok := addEarned(g.protocolEarned, protoAmt)
			if !ok {
				panic("protocol earned overflow")
			}
			g.protocolEarned = next
		}
		rest = compound
		g.lastHarvest = profit
		chain.Emit("Reinvest",
			"caller", cur.Previous().Address().String(),
			"profit", strconv.FormatInt(profit, 10),
			"compound", strconv.FormatInt(compound, 10),
			"protocol", strconv.FormatInt(protoAmt, 10),
		)
	}

	deployed := rebalance(cur)
	g.lastDeployed = deployed
	g.guard.LastUnix = now
	g.guard.LastHeight = height
	if profit == 0 && deployed == 0 {
		panic("nothing to harvest or deploy")
	}
	return rest
}

func SetBufferBPS(cur realm, bps int64) {
	mustAdmin(cur)
	if bps < 500 || bps > 5_000 {
		panic("buffer must be 5%-50%")
	}
	g.bufferBPS = bps
}

func TransferAdmin(cur realm, next address) {
	mustAdmin(cur)
	if next == address("") {
		panic("empty admin")
	}
	g.admin = next
}

func SetTreasury(cur realm, next address) {
	mustAdmin(cur)
	if next == address("") {
		panic("empty treasury")
	}
	g.treasury = next
}

func SetFees(cur realm, callerBPS, protocolBPS int64) {
	mustAdmin(cur)
	next := core.FeeConfig{CallerBPS: callerBPS, ProtocolBPS: protocolBPS}
	next.Validate()
	g.fees = next
}

func SetPaused(cur realm, next bool) {
	mustAdmin(cur)
	g.paused = next
}

func mustAdmin(cur realm) {
	if cur.Previous().Address() != g.admin {
		panic("admin only")
	}
}

func mustLive() {
	if g.paused {
		panic("paused")
	}
}

func addEarned(a, b int64) (int64, bool) {
	if a > 0 && b > 9223372036854775807-a {
		return 0, false
	}
	return a + b, true
}

func Render(path string) string {
	_ = path
	out := "# Gno Vault Strategy — Phase 1 LP farm (v3)\n\n"
	out += "WUGNOT in. 15% idle. Rest in GnoSwap GNS/WUGNOT. Withdraw unwinds LP then marks book to cash.\n\n"
	out += ufmt.Sprintf("- **TVL (book)**: %d wugnot\n", g.book.TotalAssets())
	out += ufmt.Sprintf("- **Idle / cash**: %d (target %d)\n", idleWugnot(), TargetIdleWugnot())
	out += ufmt.Sprintf("- **Pending GNS**: %d\n", pendingGns())
	out += ufmt.Sprintf("- **Share price (1e6)**: %d\n", SharePriceE6())
	out += ufmt.Sprintf("- **Shares**: %d\n", g.book.TotalShares())
	out += ufmt.Sprintf("- **LP position**: %d\n", g.positionID)
	out += ufmt.Sprintf("- **Protocol earned**: %d wugnot\n", g.protocolEarned)
	out += ufmt.Sprintf("- **Last harvest**: %d wugnot\n", g.lastHarvest)
	out += "- **Vault**: " + sanitize.InlineText(g.self.String()) + "\n"
	out += "- **Admin**: " + sanitize.InlineText(g.admin.String()) + "\n"
	return out
}

package gsfarmv3

import (
	"chain"
	"strconv"
	"time"

	"gno.land/r/gnoland/wugnot"
	"gno.land/r/gnoswap/access"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/position"
	"gno.land/r/gnoswap/router"
)

const (
	liveGnsKey        = "gno.land/r/gnoswap/gns.GNS"
	liveWugnotKey     = "gno.land/r/gnoland/wugnot.wugnot"
	liveGnsToWugnot   = "gno.land/r/gnoswap/gns.GNS:gno.land/r/gnoland/wugnot.wugnot:3000"
	liveWugnotToGns   = "gno.land/r/gnoland/wugnot.wugnot:gno.land/r/gnoswap/gns.GNS:3000"
	routerPkg         = "gno.land/r/gnoswap/router"
	poolRole          = "pool"
	feeTier           = uint32(3000)
	tickLower         = int32(-887220)
	tickUpper         = int32(887220)
	maxApprove  int64 = 1_000_000_000_000_000
)

func pullWugnot(cur realm, from address, amount int64) {
	wugnot.TransferFrom(cross(cur), from, cur.Address(), amount)
}

func pushWugnot(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	wugnot.Transfer(cross(cur), to, amount)
}

func idleWugnot() int64 { return wugnot.BalanceOf(g.self) }
func pendingGns() int64 { return gns.BalanceOf(g.self) }

func harvestLP(cur realm) int64 {
	before := wugnot.BalanceOf(cur.Address())
	if g.positionID != 0 && !position.IsBurned(g.positionID) {
		position.CollectFee(cross(cur), g.positionID)
	}
	swapAllGns(cur)
	after := wugnot.BalanceOf(cur.Address())
	if after <= before {
		return 0
	}
	return after - before
}

func swapAllGns(cur realm) {
	amt := gns.BalanceOf(cur.Address())
	if amt <= 0 {
		return
	}
	swapExact(cur, liveGnsKey, liveWugnotKey, liveGnsToWugnot, amt)
}

func swapExact(cur realm, tokenIn, tokenOut, route string, amount int64) {
	if amount <= 0 {
		return
	}
	approveSpend(cur, tokenIn, chain.PackageAddress(routerPkg), amount)
	deadline := time.Now().Unix() + 300
	router.ExactInSingleSwapRoute(
		cross(cur),
		tokenIn,
		tokenOut,
		strconv.FormatInt(amount, 10),
		route,
		"0",
		"0",
		deadline,
		"",
	)
}

func approveSpend(cur realm, tokenKey string, spender address, amount int64) {
	if tokenKey == liveWugnotKey {
		wugnot.Approve(cross(cur), spender, amount)
		return
	}
	if tokenKey == liveGnsKey {
		gns.Approve(cross(cur), spender, amount)
		return
	}
	panic("unknown token")
}

func poolAddr() address {
	return access.MustGetAddress(poolRole)
}

func approvePool(cur realm) {
	pa := poolAddr()
	wugnot.Approve(cross(cur), pa, maxApprove)
	gns.Approve(cross(cur), pa, maxApprove)
}

package gsfarmv3

import (
	"strconv"
	"time"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/alloc"
	"gno.land/r/gnoland/wugnot"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/position"
)

func ensureIdle(cur realm, need int64) {
	if wugnot.BalanceOf(cur.Address()) >= need {
		return
	}
	unwindAll(cur)
}

func unwindAll(cur realm) {
	if g.positionID == 0 {
		swapAllGns(cur)
		return
	}
	if position.IsBurned(g.positionID) {
		g.positionID = 0
		swapAllGns(cur)
		return
	}
	// CollectFee first so owed fees are not left in the NFT.
	position.CollectFee(cross(cur), g.positionID)
	liq := position.GetPositionLiquidity(g.positionID)
	if liq != "" && liq != "0" {
		deadline := time.Now().Unix() + 300
		position.DecreaseLiquidity(cross(cur), g.positionID, liq, "0", "0", deadline)
	}
	if !position.IsBurned(g.positionID) {
		position.CollectFee(cross(cur), g.positionID)
	}
	if position.IsBurned(g.positionID) {
		g.positionID = 0
	}
	swapAllGns(cur)
}

// syncBookToCash sets the share book to the WUGNOT actually held after
// unwind/swap so PreviewRedeem never promises more than the vault can pay.
func syncBookToCash() {
	have := idleWugnot()
	booked := g.book.TotalAssets()
	if booked > have {
		g.book.TakeLoss(booked - have)
		return
	}
	if have > booked && g.book.TotalShares() > 0 {
		g.book.AddProfit(have - booked)
	}
}

// rebalance deploys idle WUGNOT above the buffer into the GNS/WUGNOT LP.
func rebalance(cur realm) int64 {
	target := alloc.TargetIdle(g.book.TotalAssets(), g.bufferBPS)
	idle := wugnot.BalanceOf(cur.Address())
	excess := alloc.ExcessIdle(idle, target, alloc.MinDeploy)
	if excess == 0 {
		return 0
	}
	half := excess / 2
	if half <= 0 {
		return 0
	}
	before := wugnot.BalanceOf(cur.Address())
	swapExact(cur, liveWugnotKey, liveGnsKey, liveWugnotToGns, half)

	wug := wugnot.BalanceOf(cur.Address()) - target
	if wug < 0 {
		wug = 0
	}
	gotGns := gns.BalanceOf(cur.Address())
	if wug == 0 || gotGns == 0 {
		swapAllGns(cur)
		return 0
	}

	approvePool(cur)
	deadline := time.Now().Unix() + 300
	if g.positionID == 0 || position.IsBurned(g.positionID) {
		id, _, _, _ := position.Mint(
			cross(cur),
			liveWugnotKey,
			liveGnsKey,
			feeTier,
			tickLower,
			tickUpper,
			strconv.FormatInt(wug, 10),
			strconv.FormatInt(gotGns, 10),
			"0",
			"0",
			deadline,
			cur.Address(),
			"",
		)
		g.positionID = id
	} else {
		position.IncreaseLiquidity(
			cross(cur),
			g.positionID,
			strconv.FormatInt(wug, 10),
			strconv.FormatInt(gotGns, 10),
			"0",
			"0",
			deadline,
		)
	}
	swapAllGns(cur)
	spent := before - wugnot.BalanceOf(cur.Address())
	if spent < 0 {
		return 0
	}
	return spent
}

package lineage

// Status of a vault version. Old versions stay frozen and keep their funds.
const (
	StatusLive   = "live"
	StatusLegacy = "legacy"
	StatusSunset = "sunset"
)

// Version is a catalog row. Stored as a value, never as a realm handle.
// Gno cannot overwrite a deployed vault, so each upgrade is a new path
// plus a pointer to the previous one.
type Version struct {
	ID        string
	Name      string
	PkgPath   string
	Predecessor string
	Successor string
	Status    string
}

// ValidStatus reports whether s is a known status.
func ValidStatus(s string) bool {
	return s == StatusLive || s == StatusLegacy || s == StatusSunset
}

// Validate checks required fields. Does not talk to the chain.
func Validate(v Version) {
	if v.ID == "" || v.Name == "" || v.PkgPath == "" {
		panic("incomplete version")
	}
	if !ValidStatus(v.Status) {
		panic("invalid status")
	}
}

// IsFrozen is true when the vault must not be mutated by an upgrade.
func IsFrozen(v Version) bool {
	return v.Status == StatusLegacy || v.Status == StatusSunset
}

package lineage

import (
	"chain"
	"chain/runtime/unsafe"

	lin "gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/lineage"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Catalog of vault versions. It never holds user funds and never calls
// into a vault. Upgrades add a row; old vaults stay frozen on their path.

var (
	admin   address
	current string
	byID    avl.Tree
)

func init() {
	admin = unsafe.OriginCaller()
}

func Admin() address  { return admin }
func CurrentID() string { return current }

func TransferAdmin(cur realm, next address) {
	mustAdmin(cur)
	if next == address("") {
		panic("empty admin")
	}
	admin = next
}

// Register adds a version. Does not pause or migrate any vault.
func Register(cur realm, id, name, pkgPath, predecessor, status string) {
	mustAdmin(cur)
	if byID.Has(id) {
		panic("id taken")
	}
	v := lin.Version{
		ID:          id,
		Name:        name,
		PkgPath:     pkgPath,
		Predecessor: predecessor,
		Status:      status,
	}
	lin.Validate(v)
	if predecessor != "" {
		pv := byID.Get(predecessor)
		if pv == nil {
			panic("unknown predecessor")
		}
		prev := pv.(lin.Version)
		if prev.Successor != "" && prev.Successor != id {
			panic("predecessor already has a successor")
		}
		prev.Successor = id
		if prev.Status == lin.StatusLive {
			prev.Status = lin.StatusLegacy
		}
		byID.Set(predecessor, prev)
	}
	byID.Set(id, v)
	if current == "" || status == lin.StatusLive {
		// only one live: demote previous current
		if current != "" && current != id {
			cv := byID.Get(current)
			if cv != nil {
				curV := cv.(lin.Version)
				if curV.Status == lin.StatusLive {
					curV.Status = lin.StatusLegacy
					byID.Set(current, curV)
				}
			}
		}
		if status == lin.StatusLive {
			current = id
		}
	}
	chain.Emit("VersionRegister", "id", id, "pkg", pkgPath, "status", status)
}

// SetCurrent points new deposits at id. Does not move funds.
func SetCurrent(cur realm, id string) {
	mustAdmin(cur)
	v := mustGet(id)
	if current != "" && current != id {
		old := mustGet(current)
		if old.Status == lin.StatusLive {
			old.Status = lin.StatusLegacy
			byID.Set(current, old)
		}
	}
	v.Status = lin.StatusLive
	byID.Set(id, v)
	current = id
	chain.Emit("VersionCurrent", "id", id)
}

// Sunset marks a version closed to new deposits. Existing positions stay.
func Sunset(cur realm, id string) {
	mustAdmin(cur)
	v := mustGet(id)
	if current == id {
		panic("cannot sunset the current version")
	}
	v.Status = lin.StatusSunset
	byID.Set(id, v)
	chain.Emit("VersionSunset", "id", id)
}

func Get(id string) lin.Version {
	v := byID.Get(id)
	if v == nil {
		return lin.Version{}
	}
	return v.(lin.Version)
}

func Current() lin.Version {
	if current == "" {
		return lin.Version{}
	}
	return Get(current)
}

func Count() int { return byID.Size() }

func IDs() []string {
	out := make([]string, 0, byID.Size())
	byID.Iterate("", "", func(key string, _ any) bool {
		out = append(out, key)
		return false
	})
	return out
}

func mustGet(id string) lin.Version {
	v := byID.Get(id)
	if v == nil {
		panic("unknown version")
	}
	return v.(lin.Version)
}

func mustAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func Render(path string) string {
	_ = path
	out := "# Gno Vault Strategy — Version lineage\n\n"
	out += "Old vaults stay frozen with their funds. New deposits go to **current**.\n\n"
	if current != "" {
		out += "- **Current**: `" + sanitize.InlineText(current) + "`\n\n"
	}
	if byID.Size() == 0 {
		out += "> [!NOTE]\n> No versions registered.\n"
		return out
	}
	out += "| ID | Status | Package | Successor |\n|---|---|---|---|\n"
	byID.Iterate("", "", func(key string, value any) bool {
		v := value.(lin.Version)
		out += "| " + sanitize.TableCell(v.ID) +
			" | " + sanitize.TableCell(v.Status) +
			" | `" + sanitize.InlineText(v.PkgPath) + "`" +
			" | " + sanitize.TableCell(v.Successor) + " |\n"
		return false
	})
	return out
}
